responseSchemaJson:
{
  "type": "object",
  "description": "Core data structure for the Close-up Master. Its function is to accurately capture the 'user's' drawing request and generate a high-quality, natural language English prompt focused on specific details.",
  "properties": {
    "analysis": {
      "type": "object",
      "description": "[Module 1: Intent Analysis] Analyze the 'user's' instructions to determine the drawing focus.",
      "properties": {
        "userInstruction": {
          "type": "string",
          "description": "Specific drawing instructions or description requirements extracted from the context."
        },
        "focusExtraction": {
          "type": "string",
          "description": "The absolute core focus of the image based on the instructions. Explicitly state what background, other characters, or secondary elements need to be excluded to ensure a pure close-up."
        }
      },
      "required": [
        "userInstruction",
        "focusExtraction"
      ],
      "propertyOrdering": [
        "userInstruction",
        "focusExtraction"
      ]
    },
    "data": {
      "type": "object",
      "description": "[Module 2: Prompt Generation] Generate natural language descriptions for AI drawing.",
      "properties": {
        "naturalLanguagePrompt": {
          "type": "string",
          "description": "A fluent, detail-rich English paragraph. This paragraph must be completely dedicated to the close-up elements specified by the 'user', describing their visual characteristics in detail. It MUST use natural language sentences. If a character appears, their Chinese name MUST be used directly."
        },
        "isNSFW": {
          "type": "boolean",
          "description": "Whether the image contains adult content."
        },
        "isBDSM": {
          "type": "boolean",
          "description": "Whether the image contains BDSM elements."
        },
        "isUncensored": {
          "type": "boolean",
          "description": "Whether the image depicts uncensored genitalia."
        }
      },
      "required": [
        "naturalLanguagePrompt",
        "isNSFW",
        "isBDSM",
        "isUncensored"
      ],
      "propertyOrdering": [
        "naturalLanguagePrompt",
        "isNSFW",
        "isBDSM",
        "isUncensored"
      ]
    },
    "test": {
      "type": "object",
      "description": "[Module 3: Testing] Contains advanced mathematics problems and solutions.",
      "properties": {
        "problemsAndSolutions": {
          "type": "array",
          "description": "A list containing 3 pairs of advanced mathematics problems and their solutions.",
          "items": {
            "type": "object",
            "properties": {
              "problem": {
                "type": "string",
                "description": "Advanced mathematics problem."
              },
              "solution": {
                "type": "string",
                "description": "Solution to the problem."
              }
            },
            "required": [
              "problem",
              "solution"
            ],
            "propertyOrdering": [
              "problem",
              "solution"
            ]
          },
          "minItems": 3,
          "maxItems": 3
        }
      },
      "required": [
        "problemsAndSolutions"
      ],
      "propertyOrdering": [
        "problemsAndSolutions"
      ]
    }
  },
  "required": [
    "analysis",
    "data",
    "test"
  ],
  "propertyOrdering": [
    "analysis",
    "data",
    "test"
  ]
}

responseSchemaParserJs:
try {
    const parts = responseJson?.candidates?.[0]?.content?.parts;
    if (!parts || !Array.isArray(parts) || parts.length === 0) {
        return { error: 'No content parts found in response' };
    }

    const potentialDataSource = parts[0];
    let rawText = '';
    if (typeof potentialDataSource === 'object' && potentialDataSource !== null && typeof potentialDataSource.text === 'string') {
        rawText = potentialDataSource.text;
    } else if (typeof potentialDataSource === 'string') {
        rawText = potentialDataSource;
    } else {
        return { error: 'Response data part is not a string or an object containing text.', rawData: potentialDataSource };
    }

    let jsonString = '';
    const firstBraceIndex = rawText.indexOf('{');
    const lastBraceIndex = rawText.lastIndexOf('}');

    if (firstBraceIndex !== -1 && lastBraceIndex !== -1 && lastBraceIndex > firstBraceIndex) {
        jsonString = rawText.substring(firstBraceIndex, lastBraceIndex + 1);
    } else {
        return { error: 'Could not find valid JSON braces {} within the response text.', rawText: rawText };
    }

    let data;
    try {
        data = JSON.parse(jsonString);
    } catch (e) {
        return { error: `Failed to parse extracted JSON: ${e.message}`, rawText: rawText, extractedJson: jsonString };
    }

    if (!data || typeof data !== 'object' || !data.data) {
       return { error: 'Parsed data is not a valid object or missing data module.', rawText: rawText, extractedJson: jsonString };
    }

    const drawingData = data.data;

    // This will be populated by the frontend API client
    const characterTags = []; 

    let finalPrompt = drawingData.naturalLanguagePrompt || '';
    finalPrompt = finalPrompt.trim();

    const nsfwTags = [];
    if (drawingData.isNSFW === true) nsfwTags.push('nsfw');
    if (drawingData.isUncensored === true) nsfwTags.push('uncensored');
    if (drawingData.isBDSM === true) nsfwTags.push('bdsm');

    if (nsfwTags.length > 0) {
        finalPrompt += `, ${nsfwTags.join(', ')}`;
    }

    return {
        generalTagsString: finalPrompt,
        characterTags: characterTags
    };

} catch (e) {
    const rawResponseTextForError = responseJson?.candidates?.[0]?.content?.parts?.[0]?.text || "Raw text not available";
    return { error: `Parser exception: ${e.message}`, rawResponseForDebugging: rawResponseTextForError, stack: e.stack };
}
